// Package usmap holds the embedded map of U.S. states and territories
// (projected SVG paths) and the projections that place a longitude/latitude
// on it. The data is generated by tools/usmap/build.sh from Census Bureau
// cartographic boundaries and gazetteer files (public domain).
package usmap

import (
	_ "embed"
	"encoding/json"
	"math"
	"strings"
	"sync"
)

//go:embed usmap.json
var mapJSON []byte

// Map is every region drawn in a W×H frame.
type Map struct {
	W, H    float64
	Regions []Region `json:"regions"`
}

// Region is one state, DC or territory.
type Region struct {
	Code    string   `json:"code"`
	Name    string   `json:"name"`
	Aliases []string `json:"aliases,omitempty"`
	D       string   `json:"d"` // SVG path data
	// Box is a labelled square for regions too small to hit (small
	// Northeast states) or drawn in a framed inset (territories).
	Box *Box `json:"box,omitempty"`
	// BBox is the extent of D: x0, y0, x1, y1.
	BBox [4]float64 `json:"bbox"`
	// Group names regions drawn with the same projection ("lower48"), so
	// neighbours can be shown around a state.
	Group string     `json:"group"`
	Proj  Projection `json:"proj"`
}

// Box is a labelled square; X, Y is its top-left corner.
type Box struct {
	X, Y, W, H float64
	Frame      bool `json:"frame,omitempty"`
}

// Projection maps longitude/latitude (degrees) to map coordinates:
// a raw projection (y up) scaled by S, flipped and offset by DX, DY.
type Projection struct {
	Kind                   string  `json:"kind"` // "albers" or "mercator"
	Lon0, Lat0, Lat1, Lat2 float64 `json:",omitempty"`
	S, DX, DY              float64
}

// Raw returns the unscaled projection of lon, lat, y up.
func (p Projection) Raw(lon, lat float64) (x, y float64) {
	const rad = math.Pi / 180
	if p.Kind == "mercator" {
		return lon * rad, math.Log(math.Tan(math.Pi/4 + lat*rad/2))
	}
	if lon > 0 { // the Aleutians cross the antimeridian
		lon -= 360
	}
	n := (math.Sin(p.Lat1*rad) + math.Sin(p.Lat2*rad)) / 2
	c := math.Cos(p.Lat1*rad)*math.Cos(p.Lat1*rad) + 2*n*math.Sin(p.Lat1*rad)
	rho0 := math.Sqrt(c-2*n*math.Sin(p.Lat0*rad)) / n
	rho := math.Sqrt(c-2*n*math.Sin(lat*rad)) / n
	th := n * (lon - p.Lon0) * rad
	return rho * math.Sin(th), rho0 - rho*math.Cos(th)
}

// Point returns the map coordinates of lon, lat.
func (p Projection) Point(lon, lat float64) (x, y float64) {
	x, y = p.Raw(lon, lat)
	return x*p.S + p.DX, -y*p.S + p.DY
}

// Load returns the embedded map.
var Load = sync.OnceValue(func() *Map {
	var m Map
	if err := json.Unmarshal(mapJSON, &m); err != nil {
		panic("usmap.json: " + err.Error())
	}
	return &m
})

// Names returns the names a region answers to: name, postal code, aliases.
func (r *Region) Names() []string {
	return append([]string{r.Name, r.Code}, r.Aliases...)
}

// Find returns the region named name (or one of its aliases or its postal
// code), ignoring case, or nil.
func (m *Map) Find(name string) *Region {
	for i := range m.Regions {
		for _, n := range m.Regions[i].Names() {
			if strings.EqualFold(n, name) {
				return &m.Regions[i]
			}
		}
	}
	return nil
}
